import {configured,db,query,mutate,remove} from './service.js';import {SUPABASE_URL,SUPABASE_PUBLISHABLE_KEY} from './config.js';const VERSION='0.4.8';import {configureCalls,stopCalls,placeCall,acceptCall,declineCall,hangup,callActive} from './calls.js';import {icon} from './icons.js';
const root=document.querySelector('#app');const state={page:'home',user:null,workspace:null,rows:{},activeChat:null,month:new Date(),listeners:[],profile:[],role:'member',version:VERSION,calendarId:null,replyTo:null,chatView:'list',schedulePerson:null};
const tabs=[['home','Accueil','home'],['calendar','Planning','calendar'],['tasks','Tâches','tasks'],['chat','Chat','chat'],['files','Fichiers','files'],['notifications','Notifications','bell'],['settings','Paramètres','settings']];
const html=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const $=(s)=>document.querySelector(s);const fmt=s=>s?new Intl.DateTimeFormat('fr-FR',{dateStyle:'medium',timeZone:'Indian/Reunion'}).format(new Date(s)):'—';const hour=s=>s?new Intl.DateTimeFormat('fr-FR',{hour:'2-digit',minute:'2-digit',timeZone:'Indian/Reunion'}).format(new Date(s)):'—';const localDate=d=>new Intl.DateTimeFormat('en-CA',{timeZone:'Indian/Reunion',year:'numeric',month:'2-digit',day:'2-digit'}).format(d);const toast=m=>{let d=document.createElement('div');d.className='toast';d.textContent=m;document.body.append(d);setTimeout(()=>d.remove(),3800)};
function btn(label,action=''){return `<button class="btn" ${action?`data-action="${action}"`:''}>${html(label)}</button>`}
function navigation(){return tabs.filter(([id])=>!['notifications','settings'].includes(id)).map(([id,n,i])=>`<button data-nav="${id}" class="${state.page===id?'active':''}">${icon(i)}<span>${n}</span></button>`).join('')}
function avatar(id,small=false){const u=state.profile.find(p=>p.id===id)||{};const name=u.display_name||'Utilisateur';return `<span class="avatar ${small?'mini':''}" style="--person:${safeColor(u.color)}" aria-hidden="true">${u.avatar_signed?`<img alt="" src="${html(u.avatar_signed)}">`:html(name.slice(0,1).toUpperCase())}</span>`}
function safeColor(color){return /^#[0-9a-fA-F]{6}$/.test(color||'')?color:'#82919f'}
function colorOf(id){return safeColor(state.profile.find(p=>p.id===id)?.color)}
function personLabel(id){return `<span class="person" style="--person:${colorOf(id)}" data-action="open-profile" data-id="${html(id||'')}">${html(person(id))}</span>`}
function renderShell(){root.innerHTML=`<div class="shell"><aside class="sidebar"><button class="brand" data-nav="home" aria-label="Retour à l’accueil"><span>MAHAVEL</span><small>STUDIO</small></button><div class="studio-id">ESPACE / ${html(state.workspace?.name||'STUDIO')}</div><nav class="nav">${navigation()}</nav><div class="sidefoot"><button class="account" data-action="open-profile" data-id="${state.user.id}">${avatar(state.user.id)}<span><strong>${html(person(state.user.id))}</strong><small>Afficher mon profil</small></span></button><button class="logout" data-action="logout">${icon('logout')} Déconnexion</button></div></aside><main class="main"><header class="topbar"><div><div class="overline">MAHAVEL / ESPACE DE PRODUCTION</div><h1 class="page-title" id="page-label"></h1></div><div class="top-actions"><span class="connection ${navigator.onLine?'':'offline'}" id="connection"><i></i><span>${navigator.onLine?'En ligne':'Hors ligne'}</span></span><button class="icon-btn" data-action="quick" aria-label="Créer rapidement" title="Créer">${icon('plus')}</button><button class="icon-btn" data-nav="notifications" aria-label="Notifications" title="Notifications">${icon('bell')}<span class="unread-badge" data-unread-badge hidden></span></button><button class="icon-btn" data-nav="settings" aria-label="Paramètres" title="Paramètres">${icon('settings')}</button><button class="avatar-button" data-action="open-profile" data-id="${state.user.id}" aria-label="Mon profil">${avatar(state.user.id,true)}</button></div></header><div class="content" id="content"></div></main></div><nav class="mobile-nav">${tabs.slice(0,5).map(([id,n,i])=>`<button data-nav="${id}" class="${id===state.page?'active':''}">${icon(i)}<span>${n}</span></button>`).join('')}</nav>`;setPersonTheme();renderPage()}
function auth(){root.innerHTML=`<section class="auth"><h1>MAHAVEL</h1><div class="sub">STUDIO / ACCÈS PRIVÉ</div>${!configured()?'<div class="alert">Configuration Supabase nécessaire.</div>':''}<form id="login"><div><label>E-mail professionnel</label><input type="email" name="email" required autocomplete="username"></div><div><label>Mot de passe</label><input type="password" name="password" required autocomplete="current-password"></div><button class="btn primary" type="submit">Se connecter</button><button class="btn ghost" type="button" data-action="show-register">Créer son compte / définir un mot de passe</button><button class="btn ghost" type="button" data-action="reset">Mot de passe oublié</button><p class="error" id="auth-error" role="alert"></p></form><p class="note">L’accès aux données MAHAVEL nécessite une invitation et l’ajout par un administrateur.</p></section>`}
function registerScreen(email=''){root.innerHTML=`<section class="auth"><h1>MAHAVEL</h1><div class="sub">CRÉER MON COMPTE</div><form id="register"><div><label>E-mail invité</label><input type="email" name="email" required autocomplete="username" value="${html(email)}"></div><div><label>Choisir un mot de passe (8 caractères minimum)</label><input type="password" name="password" minlength="8" autocomplete="new-password" required></div><div><label>Confirmer le mot de passe</label><input type="password" name="confirm" minlength="8" autocomplete="new-password" required></div><button class="btn primary" type="submit">Créer mon compte</button><button class="btn ghost" type="button" data-action="show-login">Retour à la connexion</button><p class="error" id="auth-error" role="alert"></p></form><p class="note">Si cette adresse possède déjà un compte, un e-mail sécurisé sera nécessaire pour attribuer un nouveau mot de passe.</p></section>`}
function passwordSetup(){
 root.innerHTML=`<section class="auth"><h1>MAHAVEL</h1><div class="sub">CRÉER MON MOT DE PASSE</div><form id="set-password"><div><label>Nouveau mot de passe</label><input type="password" name="password" required minlength="8" autocomplete="new-password"></div><div><label>Confirmer le mot de passe</label><input type="password" name="confirm" required minlength="8" autocomplete="new-password"></div><button type="submit" class="btn primary">Enregistrer mon mot de passe</button><p class="error" id="auth-error" role="alert"></p></form><p class="note">Choisissez un mot de passe personnel d'au moins 8 caractères. Ne le transmettez à personne.</p></section>`;
}
async function initialize(){
 if(!configured()){auth();return}
 try{
  const client=await db();
  // IMPORTANT : ne pas lancer de requêtes Supabase depuis onAuthStateChange.
  // Supabase conserve un verrou de session pendant ses notifications d'authentification.
  const {data:{session},error:sessionError}=await client.auth.getSession();
  if(sessionError)throw sessionError;
  state.user=session?.user||null;
  client.auth.onAuthStateChange((event,nextSession)=>{
   if(event==='INITIAL_SESSION')return;
   if(event==='PASSWORD_RECOVERY'){
    state.user=nextSession?.user||null;
    setTimeout(()=>passwordSetup(),0);
    return;
   }
   const nextUser=nextSession?.user||null;
   if(state.user?.id!==nextUser?.id){
    stopCalls();
    state.user=nextUser;
    setTimeout(()=>loadWorkspace().catch(err=>{console.error('MAHAVEL session',err);root.innerHTML='<section class="auth"><h1>MAHAVEL</h1><p class="error">Échec de la connexion : '+html(err.message)+'</p><button class="btn" onclick="location.reload()">Réessayer</button></section>'}),0);
   }
  });
  if(location.hash.includes('type=recovery')){passwordSetup();return}
  await loadWorkspace();
 }catch(e){
  console.error('MAHAVEL startup',e);
  root.innerHTML=`<section class="auth"><h1>Connexion indisponible</h1><p class="error">${html(e.message)}</p>${btn('Réessayer','retry')}</section>`;
 }
}
async function loadWorkspace(){if(!state.user){auth();return}try{const s=await db();const {data,error}=await s.from('memberships').select('role,workspace_id,workspaces(id,name)').eq('user_id',state.user.id).limit(1).maybeSingle();if(error)throw error;if(!data){root.innerHTML=`<section class="auth"><h1>MAHAVEL</h1><p>Votre compte est connecté, mais il n'appartient à aucun espace de travail.</p><p class="note">Demandez à l'administrateur de vous ajouter dans la table memberships (voir README).</p>${btn('Déconnexion','logout')}</section>`;return}state.workspace=data.workspaces;state.role=data.role;await refresh();await realtime();renderShell();configureCalls({client:s,userId:state.user.id,workspaceId:state.workspace.id,incoming:incomingCall,ended:()=>{if(document.querySelector(".call-panel"))close()}})}catch(e){root.innerHTML=`<section class="auth"><h1>Accès non disponible</h1><p class="error">${html(e.message)}</p>${btn('Déconnexion','logout')}</section>`}}
const resources=['projects','tasks','events','conversations','messages','documents','external_links','notifications','approvals','studio_calendars','profile_schedules','hidden_conversations'];
async function refresh(){if(!state.workspace)return;state.loadErrors=[];await Promise.all(resources.map(async k=>{try{state.rows[k]=await query(k,state.workspace.id)}catch(e){state.rows[k]=[];state.loadErrors.push(k);console.warn(k,e.message)}}));const s=await db();if(state.rows.conversations?.length){const {data:members}=await s.from('conversation_members').select('*').in('conversation_id',state.rows.conversations.map(c=>c.id));state.rows.conversation_members=members||[]}else state.rows.conversation_members=[];const receipts=await s.from('conversation_reads').select('conversation_id,read_at').eq('user_id',state.user.id);state.rows.conversation_reads=receipts.error?[]:receipts.data||[];const msgs=state.rows.messages||[];for(const table of ['message_reactions','saved_messages']){if(msgs.length){const {data,error}=await s.from(table).select('*').in('message_id',msgs.map(m=>m.id));state.rows[table]=error?[]:data||[];if(error)console.warn(table,error.message)}else state.rows[table]=[]}const {data}=await s.from('profiles').select('id,display_name,color,avatar_url,job_title,contact_url,contact_email').limit(100);state.profile=data||[];await Promise.all(state.profile.filter(p=>p.avatar_url).map(async p=>{try{const {data,error}=await s.storage.from('studio-avatars').createSignedUrl(p.avatar_url,1800);if(!error)p.avatar_signed=data.signedUrl}catch{}}));setPersonTheme()}
async function realtime(){const s=await db();for(const c of state.listeners)await s.removeChannel(c);state.listeners=[];const c=s.channel('workspace-'+state.workspace.id);for(const t of resources)c.on('postgres_changes',{event:'*',schema:'public',table:t,filter:`workspace_id=eq.${state.workspace.id}`},async()=>{await refresh();renderPage()});for(const t of ['message_reactions','saved_messages'])c.on('postgres_changes',{event:'*',schema:'public',table:t},async()=>{await refresh();renderPage()});c.subscribe();state.listeners.push(c)}
const unreadCount=c=>{const read=items('conversation_reads').find(x=>x.conversation_id===c.id)?.read_at||'1970-01-01';return items('messages').filter(m=>m.conversation_id===c.id&&m.author_id!==state.user.id&&m.created_at>read).length};async function markChatRead(cid){if(!cid)return;const client=await db();const readAt=new Date().toISOString();const {error}=await client.from('conversation_reads').upsert({conversation_id:cid,user_id:state.user.id,read_at:readAt},{onConflict:'conversation_id,user_id'});if(error){console.warn('Lecture',error.message);return}const previous=items('conversation_reads').find(x=>x.conversation_id===cid);if(previous)previous.read_at=readAt;else{state.rows.conversation_reads=items('conversation_reads').concat({conversation_id:cid,read_at:readAt})}renderUnreadBadges()};function renderUnreadBadges(){const total=items('conversations').reduce((n,c)=>n+unreadCount(c),0)+items('notifications').filter(n=>n.user_id===state.user.id&&!n.read_at).length;document.querySelectorAll('[data-unread-badge]').forEach(el=>{el.textContent=total?String(total):'';el.hidden=!total})}const person=id=>state.profile.find(p=>p.id===id)?.display_name||'Collaborateur';const items=(k)=>state.rows[k]||[];const row=(title,sub,tag,id,kind)=>`<div class="list-row ${id?'click':''}" ${id?`data-open="${kind}:${id}"`:''}><div class="list-main"><div class="list-title">${html(title)}</div><div class="meta">${html(sub)}</div></div>${tag?`<span class="pill" data-status="${html(tag)}">${html(tag)}</span>`:''}</div>`;
function renderPage(){if(!$('#content'))return;const page=state.page;$('#page-label').textContent=tabs.find(a=>a[0]===page)?.[1]||'Studio';document.querySelectorAll('[data-nav]').forEach(n=>n.classList.toggle('active',n.dataset.nav===page));let result='';try{result=({home:homePage,calendar:calendarPage,tasks:tasksPage,chat:chatPage,files:filesPage,projects:projectsPage,availability:availabilityPage,notifications:notificationsPage,settings:settingsPage})[page]()}catch(e){result=`<div class="alert">${html(e.message)}</div>`}$('#content').innerHTML=(state.loadErrors?.length?`<div class="alert" role="status">Certaines données n'ont pas pu être chargées (${html(state.loadErrors.join(', '))}). Vérifiez votre connexion et les permissions Supabase. <button type="button" class="btn small" data-action="retry-data">Réessayer</button></div>`:'')+result;renderUnreadBadges();if(page==='chat'&&state.chatView==='thread')requestAnimationFrame(()=>{const area=$('#message-area');if(area)area.scrollTop=area.scrollHeight})}
function homePage(){let tasks=items('tasks').filter(t=>t.assignee_id===state.user.id&&t.status!=='Terminé').slice(0,6),ev=items('events').filter(e=>localDate(new Date(e.starts_at))===localDate(new Date())).sort((a,b)=>a.starts_at.localeCompare(b.starts_at));const docs=items('documents').slice(0,5);return `<div class="sectionbar"><h2>Ma journée <span class="muted">/ ${html(fmt(new Date()))}</span></h2><div class="controls">${btn('+ Tâche','new-task')}${btn('+ Événement','new-event')}</div></div><div class="dashboard"><section class="panel"><div class="panelhead">MES TÂCHES <span>${tasks.length} affichée(s)</span></div>${tasks.length?tasks.map(t=>row(t.title,(t.due_at?'Échéance '+fmt(t.due_at):'Sans échéance'),t.status,t.id,'task')).join(''):'<div class="empty">Aucune tâche personnelle en cours</div>'}</section><section class="panel"><div class="panelhead">AUJOURD’HUI <span>${ev.length} événement(s)</span></div>${ev.length?ev.map(e=>row(e.title,hour(e.starts_at)+' – '+hour(e.ends_at),e.category,e.id,'event')).join(''):'<div class="empty">Aucun événement aujourd’hui</div>'}</section><section class="panel"><div class="panelhead">DERNIERS DOCUMENTS</div>${docs.length?docs.map(d=>row(d.name,person(d.author_id)+' · '+fmt(d.created_at),d.keep?'À conserver':'Temporaire',d.id,'document')).join(''):'<div class="empty">Aucun document disponible</div>'}</section><section class="panel"><div class="panelhead">EN ATTENTE DE VALIDATION</div>${items('tasks').filter(t=>t.status==='À valider').slice(0,5).map(t=>row(t.title,person(t.assignee_id),t.status,t.id,'task')).join('')||'<div class="empty">Aucune validation en attente</div>'}</section></div>`}
function tasksPage(){return `<div class="sectionbar"><h2>Production / tâches</h2><div class="controls"><select id="task-filter"><option value="all">Toutes les tâches</option><option value="mine">Mes tâches</option><option value="pending">À valider</option></select>${btn('Importer des tâches','import-task')}${btn('+ Nouvelle tâche','new-task')}</div></div><div class="panel table-wrap"><table class="data-table"><thead><tr><th>Tâche</th><th>Responsable</th><th>Échéance</th><th>Priorité</th><th>Statut</th></tr></thead><tbody id="task-table">${taskRows()}</tbody></table></div>`}
function taskRows(filter='all'){const data=items('tasks').filter(t=>filter==='all'||(filter==='mine'&&t.assignee_id===state.user.id)||(filter==='pending'&&t.status==='À valider'));return data.map(t=>`<tr data-id="${t.id}" data-open="task:${t.id}" style="--person:${colorOf(t.assignee_id)}"><td><b>${html(t.title)}</b><div class="meta">${html(t.description||'')}</div></td><td>${personLabel(t.assignee_id)}</td><td>${html(fmt(t.due_at))}</td><td>${html(t.priority)}</td><td><span class="pill" data-status="${html(t.status)}">${html(t.status)}</span></td></tr>`).join('')||'<tr><td colspan="5" class="empty">Aucune tâche</td></tr>'}
function calendarPage(){const all=items('studio_calendars'),cal=selectedCalendar();const d=state.month,year=d.getFullYear(),month=d.getMonth(),start=new Date(year,month,1),offset=(start.getDay()+6)%7,days=new Date(year,month+1,0).getDate();let cells=['LUN','MAR','MER','JEU','VEN','SAM','DIM'].map(n=>`<div class="calweek">${n}</div>`).join('');for(let i=0;i<Math.ceil((offset+days)/7)*7;i++){const day=i-offset+1;let date=new Date(year,month,day),key=localDate(date),ev=items('events').filter(e=>(!cal||e.calendar_id===cal.id)&&localDate(new Date(e.starts_at))===key);cells+=`<div class="calday ${date.getMonth()!==month?'dim':''} ${key===localDate(new Date())?'today':''}"><div class="caldate">${day}</div>${ev.slice(0,3).map(e=>`<button class="calevent" style="--person:${colorOf(e.responsible_id||e.created_by)}" data-open="event:${e.id}">${html(hour(e.starts_at))} ${html(e.title)}</button>`).join('')}${ev.length>3?`<div class="meta">+${ev.length-3}</div>`:''}</div>`}return `<div class="sectionbar calendar-toolbar"><div class="controls"><button class="btn small" data-action="prev-month" aria-label="Mois précédent">‹</button><h2>${html(new Intl.DateTimeFormat('fr-FR',{month:'long',year:'numeric'}).format(d))}</h2><button class="btn small" data-action="next-month" aria-label="Mois suivant">›</button>${btn('Aujourd’hui','today')}</div><div class="controls"><label class="selector-label">Planning <select id="calendar-selector">${all.map(c=>`<option value="${c.id}" ${cal?.id===c.id?'selected':''}>${html(c.name)}</option>`).join('')}</select></label>${btn('+ Événement','new-event')}</div></div><div class="calendar-utilities"><span class="meta">${html(cal?.description||'Choisissez un planning dans la liste.')}</span><div class="controls">${btn('+ Créer un planning','new-calendar')}${btn('Importer un planning','import-calendar')}${cal&&!cal.is_default?`<button class="btn" data-action="edit-calendar" data-id="${cal.id}">Renommer / modifier</button>`:''}${cal&&!cal.is_default?`<button class="btn danger" data-action="delete-calendar" data-id="${cal.id}">Supprimer ce planning</button>`:''}</div></div><div class="calendar">${cells}</div><div class="statusline">Fuseau horaire de référence : La Réunion (UTC+4)</div>`}
function projectsPage(){return `<div class="sectionbar"><h2>Productions</h2>${btn('+ Projet','new-project')}</div><div class="panel">${items('projects').map(p=>row(p.name,p.category+' · '+(p.description||''),p.status,p.id,'project')).join('')||'<div class="empty">Aucun projet</div>'}</div>`}
function availabilityPage(){return `<div class="sectionbar"><h2>Disponibilités / équipe</h2>${btn('+ Indisponibilité','new-availability')}</div><div class="panel">${items('availability').map(a=>row(person(a.user_id)+' — '+a.label,fmt(a.starts_at)+' '+hour(a.starts_at)+' → '+fmt(a.ends_at)+' '+hour(a.ends_at),a.kind,a.id,'availability')).join('')||'<div class="empty">Aucune indisponibilité déclarée</div>'}</div>`}
function conversationTitle(c){if(c.kind!=='Direct')return c.name;const other=items('conversation_members').find(m=>m.conversation_id===c.id&&m.user_id!==state.user.id);return other?person(other.user_id):'Conversation privée'}
function chatPage(){const cs=items('conversations').filter(c=>{const h=items('hidden_conversations').find(x=>x.conversation_id===c.id&&x.user_id===state.user.id);return !h||items('messages').some(m=>m.conversation_id===c.id&&m.created_at>h.hidden_at&&m.author_id!==state.user.id)});const current=cs.find(c=>c.id===state.activeChat);const ms=items('messages').filter(m=>m.conversation_id===state.activeChat).sort((a,b)=>a.created_at.localeCompare(b.created_at));const reply=msgById(state.replyTo);return `<div class="chat-app ${current&&state.chatView==='thread'?'show-thread':''}"><section class="chat-list"><div class="chat-list-header"><div><h2>Messages</h2><span class="meta">Conversations privées et groupes</span></div><button class="icon-btn accent" data-action="new-conversation" aria-label="Nouvelle conversation">${icon('plus')}</button></div><div class="chat-tools"><label class="sr-only" for="chat-search">Rechercher une conversation</label><input type="search" id="chat-search" placeholder="Rechercher un contact ou un groupe" value="${html(state.chatSearch||'')}"><button type="button" class="btn small" data-action="show-saved">${icon('bookmark')} Messages enregistrés</button></div><div class="chat-list-body">${cs.filter(c=>conversationTitle(c).toLocaleLowerCase('fr').includes((state.chatSearch||'').toLocaleLowerCase('fr'))).map(c=>{const participants=items('conversation_members').filter(m=>m.conversation_id===c.id);const other=participants.find(m=>m.user_id!==state.user.id);const pic=other?avatar(other.user_id,true):`<span class="avatar mini">${icon('chat')}</span>`;return `<button class="chat-contact ${current?.id===c.id?'selected':''}" data-chat-id="${c.id}" data-action="select-chat" data-chat="${c.id}">${pic}<span class="chat-contact-main"><b>${html(conversationTitle(c))}</b><small>${html(c.kind==='Direct'?'Conversation privée':c.kind)}</small></span>${unreadCount(c)?`<span class="unread-badge in-list">${unreadCount(c)}</span>`:''}<span class="chat-chevron">›</span></button>`}).join('')||'<div class="empty">Aucune conversation. Créez un chat avec un collègue.</div>'}</div></section><section class="chat-thread ${current?'':'chat-empty'}">${current?`<div class="chat-thread-header"><button class="back-chat" type="button" data-action="back-chat" aria-label="Fermer et revenir aux discussions">←</button><div class="chat-peer"><b>${html(conversationTitle(current))}</b><span class="meta">${html(current.kind==='Direct'?'Conversation privée':'Groupe')}</span></div><div class="chat-toolbar">${current.kind==='Direct'?`<button type="button" class="chat-tool" data-action="start-call" data-kind="audio" aria-label="Appel audio" title="Appel audio">${icon('phone')}</button><button type="button" class="chat-tool" data-action="start-call" data-kind="video" aria-label="Appel vidéo" title="Appel vidéo">${icon('video')}</button>`:''}<button type="button" class="chat-tool chat-more" data-action="chat-options" aria-label="Options de la discussion" title="Options de la discussion">···</button></div></div><div class="chat-thread-messages" id="message-area">${ms.map(messageMarkup).join('')||'<div class="empty">Aucun message pour le moment</div>'}</div>${reply?`<div class="reply-preview"><div><span>Réponse à ${html(person(reply.author_id))}</span><p>${html(reply.body.slice(0,150))}</p></div><button class="icon-btn" data-action="cancel-reply" aria-label="Annuler la réponse">×</button></div>`:''}<form class="composer" id="send-message"><input aria-label="Message" name="message" placeholder="Écrire un message…" maxlength="4000" required><button class="btn primary">Envoyer</button></form>`:`<div class="chat-welcome">${icon('chat')}<h2>Vos conversations</h2><p>Sélectionne une discussion ou crée un nouveau chat privé.</p></div>`}</section></div>`}
function filesPage(){return `<div class="sectionbar"><h2>Fichiers / partage d’équipe</h2></div><div class="file-main-actions"><button class="file-action" data-action="new-file">${icon('files')}<span><strong>+ Fichier</strong><small>Importer un document</small></span></button><button class="file-action" data-action="new-link">${icon('share')}<span><strong>+ Lien</strong><small>Ajouter une ressource externe</small></span></button></div><section class="panel"><div class="panelhead">FICHIERS PRIVÉS</div>${items('documents').map(d=>row(d.name,`${Math.ceil(d.size_bytes/1024)} Ko · ${person(d.author_id)} · ${d.keep?'Protégé':'Expire le '+fmt(d.expires_at)}`,d.keep?'À conserver':'Temporaire',d.id,'document')).join('')||'<div class="empty">Aucun fichier</div>'}</section><section class="panel" style="margin-top:17px"><div class="panelhead">LIENS EXTERNES</div>${items('external_links').map(l=>row(l.title,l.url,'Lien',l.id,'link')).join('')||'<div class="empty">Aucun lien</div>'}</section>`}
function notificationsPage(){return `<div class="panel"><div class="panelhead">ACTIVITÉ INTERNE</div>${items('notifications').filter(n=>n.user_id===state.user.id).map(n=>`<button class="notification-entry ${n.read_at?'':'new'}" data-action="read-notification" data-id="${n.id}"><strong>${html(n.title)}</strong><span>${html(n.body||fmt(n.created_at))}</span><em>${n.read_at?'Lu':'Marquer comme lu'}</em></button>`).join('')||'<div class="empty">Aucune notification</div>'}</div>`}
function profileEditor(id=state.user.id){let u=state.profile.find(p=>p.id===id)||{},self=id===state.user.id;modal('Profil / '+person(id),`<div class="profile-header">${avatar(id)}<div><strong>${html(person(id))}</strong><div class="meta">${html(u.job_title||'Membre de MAHAVEL')}</div><div class="meta">${html(u.contact_email|| (self?state.user.email:'Adresse non renseignée'))}</div></div></div>${u.contact_url?`<p><a href="${html(u.contact_url)}" target="_blank" rel="noopener noreferrer">Lien de contact ↗</a></p>`:''}<div class="profile-actions"><button class="btn" data-action="open-schedule" data-person="${id}">${icon('clock')} Voir l’emploi du temps</button></div>${self?`<form data-form="profile" class="formgrid"><div class="full">${formField('Nom affiché','display_name',u.display_name||'','text','required maxlength="80"')}</div><div>${formField('Fonction','job_title',u.job_title||'')}</div><div><label>Couleur personnelle</label><input type="color" name="color" value="${safeColor(u.color)}"></div><div class="full">${formField('Lien de contact HTTPS','contact_url',u.contact_url||'','url')}</div><div class="full"><label>Photo (JPG, PNG ou WebP, 2 Mo maximum)</label><input type="file" name="avatar" accept="image/jpeg,image/png,image/webp"></div><div class="full actions"><button class="btn primary">Enregistrer mon profil</button></div></form>`:''}`)}
function quickMenu(){modal('Créer rapidement',`<div class="quick-grid"><button class="btn" data-action="new-task">+ Tâche</button><button class="btn" data-action="new-event">+ Rendez-vous</button><button class="btn" data-action="new-conversation">+ Conversation</button><button class="btn" data-action="new-file">+ Fichier</button><button class="btn" data-action="new-calendar">+ Planning</button><button class="btn" data-action="import-task">Importer des tâches</button></div>`)}
function deleteControl(kind,id){return `<button type="button" class="btn danger" data-action="delete-item" data-kind="${kind}" data-id="${id}">Supprimer</button>`}
function settingsPage(){return `<div class="utility"><div class="sectionbar"><h2>Paramètres de votre espace</h2></div><div class="panel"><div class="settings-row flex-between"><div><b>Profil personnel</b><div class="meta">Pseudo, couleur, photo et contact</div></div>${btn('Personnaliser','open-my-profile')}</div><div class="settings-row flex-between"><div><b>Emploi du temps</b><div class="meta">Créneaux liés à votre profil, import au format JSON</div></div>${btn('Voir mon emploi du temps','open-my-schedule')}</div><div class="settings-row flex-between"><div><b>Version ${VERSION}</b><div class="meta">Mise à jour PWA</div></div>${btn('Rechercher les mises à jour','update')}</div><div class="settings-row"><b>Conservation</b><p class="note">Messages : 7 jours sauf ceux enregistrés. Fichiers : 6 jours sauf « À conserver ». Le nettoyage des fichiers exige le déploiement de la fonction cleanup-expired-files et une exécution planifiée côté serveur.</p></div><div class="settings-row">${btn('Réinitialiser mon mot de passe','reset')} <button class="btn danger" data-action="logout">Déconnexion</button></div></div></div>`}
function modal(title,body){const overlay=document.createElement('div');overlay.className='modalbg';overlay.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-label="${html(title)}"><div class="flex-between"><h2>${html(title)}</h2><button class="btn small" data-action="close">✕</button></div>${body}</section>`;document.body.append(overlay);overlay.addEventListener('click',e=>{if(e.target===overlay&&!overlay.querySelector('form input:focus, form textarea:focus'))overlay.remove()})}
const options=(values,selected)=>values.map(v=>`<option ${v===selected?'selected':''}>${html(v)}</option>`).join('');const formField=(title,name,val='',type='text',extra='')=>`<div><label>${html(title)}</label><input name="${name}" type="${type}" value="${html(val)}" ${extra}></div>`;
function taskForm(t={}){const people=state.profile.map(p=>`<option value="${p.id}" ${p.id===(t.assignee_id||state.user.id)?'selected':''}>${html(p.display_name)}</option>`).join('');modal(t.id?'Modifier la tâche':'Nouvelle tâche',`<form data-form="task" data-id="${t.id||''}" class="formgrid">${formField('Titre *','title',t.title||'','text','required maxlength="200"')}<div><label>Responsable</label><select name="assignee_id">${people}</select></div><div><label>Projet</label><select name="project_id"><option value="">Aucun</option>${items('projects').map(p=>`<option value="${p.id}" ${p.id===t.project_id?'selected':''}>${html(p.name)}</option>`).join('')}</select></div><div class="full"><label>Description</label><textarea name="description">${html(t.description||'')}</textarea></div><div><label>Priorité</label><select name="priority">${options(['Normale','Haute','Urgente'],t.priority||'Normale')}</select></div><div><label>Statut</label><select name="status">${options(['À faire','En cours','En attente','À valider','Corrections demandées','Terminé','Archivé'],t.status||'À faire')}</select></div>${formField('Échéance','due_at',t.due_at?.slice(0,10)||'','date')}<div class="full actions">${t.id?deleteControl('task',t.id):''}<button class="btn primary">Enregistrer</button></div></form>`)}
function eventForm(t={}){const toInput=s=>{if(!s)return '';const parts=new Intl.DateTimeFormat('en-CA',{timeZone:'Indian/Reunion',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(s));const v=Object.fromEntries(parts.map(x=>[x.type,x.value]));return `${v.year}-${v.month}-${v.day}T${v.hour}:${v.minute}`};const calendars=items('studio_calendars');modal(t.id?'Modifier l’événement':'Nouvel événement',`<form data-form="event" data-id="${t.id||''}" class="formgrid">${formField('Titre *','title',t.title||'','text','required')}<div><label>Planning</label><select name="calendar_id">${calendars.map(c=>`<option value="${c.id}" ${c.id===(t.calendar_id||selectedCalendar()?.id)?'selected':''}>${html(c.name)}</option>`).join('')}</select></div><div><label>Catégorie</label><select name="category">${options(['Tournage','Montage','Réunion','Interview','Rendez-vous','Publication','Livraison','Déplacement','Autre'],t.category||'Tournage')}</select></div>${formField('Début *','starts_at',toInput(t.starts_at),'datetime-local','required')}${formField('Fin *','ends_at',toInput(t.ends_at),'datetime-local','required')}<div><label>Responsable / couleur</label><select name="responsible_id"><option value="">Non attribué</option>${state.profile.map(p=>`<option value="${p.id}" ${p.id===t.responsible_id?'selected':''}>${html(p.display_name)}</option>`).join('')}</select></div>${formField('Lieu','location',t.location||'')}<div class="full"><label>Notes</label><textarea name="description">${html(t.description||'')}</textarea></div><div class="full actions">${t.id?deleteControl('event',t.id):''}<button class="btn primary">Enregistrer</button></div></form>`)}
function projectForm(t={}){modal(t.id?'Modifier le projet':'Nouveau projet',`<form data-form="project" data-id="${t.id||''}" class="formgrid">${formField('Nom *','name',t.name||'','text','required')}<div><label>Catégorie</label><select name="category">${options(['Vidéo','Communication','Réseaux sociaux','Graphisme','Événement','Campagne','Projet interne'],t.category||'Vidéo')}</select></div><div><label>Statut</label><select name="status">${options(['Préparation','En cours','En attente','En validation','Livré','Archivé'],t.status||'Préparation')}</select></div><div class="full"><label>Description</label><textarea name="description">${html(t.description||'')}</textarea></div><div class="full actions">${t.id?deleteControl('project',t.id):''}<button class="btn primary">Enregistrer</button></div></form>`)}
function toReunionInput(s){if(!s)return '';const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Indian/Reunion',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(s));const v=Object.fromEntries(parts.map(x=>[x.type,x.value]));return `${v.year}-${v.month}-${v.day}T${v.hour}:${v.minute}`}
function availabilityForm(a={}){modal('Indisponibilité',`<form data-form="availability" data-id="${a.id||''}" class="formgrid"><div><label>Collaborateur</label><select name="user_id">${state.profile.filter(p=>state.role!=='member'||p.id===state.user.id).map(p=>`<option value="${p.id}" ${p.id===(a.user_id||state.user.id)?'selected':''}>${html(p.display_name)}</option>`).join('')}</select></div>${formField('Motif *','label',a.label||'','text','required')}<div><label>Type</label><select name="kind">${options(['Indisponible','Absence','Disponible'],a.kind||'Indisponible')}</select></div>${formField('Début','starts_at',toReunionInput(a.starts_at),'datetime-local','required')}${formField('Fin','ends_at',toReunionInput(a.ends_at),'datetime-local','required')}<div class="full actions">${a.id?deleteControl('availability',a.id):''}<button class="btn primary">Enregistrer</button></div></form>`)}
function conversationForm(){const choices=state.profile.filter(p=>p.id!==state.user.id).map(p=>`<label class="recipient-choice"><input type="checkbox" name="recipients" value="${p.id}">${avatar(p.id,true)}<span>${html(p.display_name)}</span></label>`).join('');modal('Nouvelle conversation',`<form data-form="conversation"><p class="note">Sélectionne une personne pour un chat privé, ou plusieurs personnes pour un groupe.</p><div class="recipient-grid">${choices||'<p class="empty">Ajoute d’abord un autre membre dans Supabase.</p>'}</div><div class="select-count" id="chat-count">0 sélectionné(e)</div><div class="group-name-wrap" id="group-name-wrap" hidden><label>Nom du groupe</label><input name="name" maxlength="120" placeholder="Ex. Équipe tournage"></div><div class="actions"><button class="btn primary" ${choices?'':'disabled'}>Créer</button></div></form>`)}
function uploadForm(){const people=state.profile.filter(p=>p.id!==state.user.id).map(p=>`<label class="recipient-choice"><input type="checkbox" name="recipients" value="${p.id}">${avatar(p.id,true)}<span>${html(p.display_name)}</span></label>`).join('');modal('Partager un fichier',`<form data-form="file" class="upload-form"><label>Fichier (50 Mo maximum selon les réglages Supabase)</label><input type="file" name="file" required><label>Visibilité</label><select name="visibility"><option value="workspace">Toute l’équipe</option><option value="targeted">Personnes sélectionnées</option></select><div id="file-recipients" hidden><label>Destinataires</label><div class="recipient-grid">${people||'<p class="note">Aucun autre collaborateur pour le moment</p>'}</div><div class="select-count" id="file-count">0 sélectionné(e)</div></div><p class="note">Les fichiers ciblés seront annoncés dans un chat privé. Pour les vidéos volumineuses, privilégiez un lien externe.</p><label class="inline-check"><input type="checkbox" name="keep"> À conserver</label><div class="actions"><button class="btn primary">Envoyer</button></div><p class="upload-progress" id="upload-progress"></p></form>`)}
function linkForm(){modal('Lien externe',`<form data-form="link">${formField('Titre','title','','text','required')}${formField('Adresse HTTPS','url','','url','required')}<div class="actions"><button class="btn primary">Ajouter le lien</button></div></form>`)}
async function openDetail(kind,id){let singular={task:'tasks',event:'events',project:'projects',document:'documents',link:'external_links',availability:'availability'};let obj=items(singular[kind]).find(x=>x.id===id);if(!obj)return;if(kind==='task'){taskForm(obj);if(obj.status==='À valider'&&['admin','manager'].includes(state.role)){const form=document.querySelector('.modal form[data-form=task]');if(form){const holder=form.querySelector('.actions');if(holder)holder.insertAdjacentHTML('afterbegin',`<button type="button" class="btn primary" data-action="approve-task" data-id="${id}">Valider la production</button><button type="button" class="btn" data-action="request-corrections" data-id="${id}">Demander des corrections</button>`)}}return;}if(kind==='event')return eventForm(obj);if(kind==='project')return projectForm(obj);if(kind==='availability')return availabilityForm(obj);if(kind==='document'){modal('Document',`<div class="list-title">${html(obj.name)}</div><p class="note">${obj.keep?'À conserver':'Expiration : '+fmt(obj.expires_at)}</p><div class="actions"><button class="btn" data-action="download" data-id="${id}">Télécharger</button><button class="btn" data-action="toggle-keep" data-id="${id}">${obj.keep?'Retirer la protection':'À conserver'}</button><button class="btn danger" data-action="delete-file" data-id="${id}">Supprimer</button></div>`);return}if(kind==='link'){modal('Lien externe',`<div class="list-title">${html(obj.title)}</div><p class="note">${html(obj.url)}</p><div class="actions"><a class="btn" href="${html(obj.url)}" target="_blank" rel="noopener noreferrer">Ouvrir</a>${deleteControl('link',id)}</div>`);return}}
function close(){document.querySelector('.modalbg')?.remove()}

let pendingCall=null;
function openCallPanel(kind,title){close();modal(title,`<div class="call-panel"><p class="note" id="studio-call-status">Connexion sécurisée entre deux collaborateurs. Autorisez le microphone${kind==='video'?' et la caméra':''}.</p><div class="call-videos">${kind==='video'?'<video id="studio-local-media" autoplay muted playsinline></video><video id="studio-remote-media" autoplay playsinline></video>':'<audio id="studio-remote-media" autoplay></audio><div class="call-audio-symbol">● AUDIO</div><video id="studio-local-media" autoplay muted playsinline hidden></video>'}</div><button class="btn danger" data-action="hangup-call">Raccrocher</button></div>`)}
function incomingCall(call){pendingCall=call;const caller=person(call.caller_id);modal('Appel entrant',`<section class="incoming-call"><div class="overline">MAHAVEL / COMMUNICATION</div><h3>${html(caller)}</h3><p>Appel ${call.media_kind==='video'?'vidéo':'audio'} entrant</p><div class="actions"><button class="btn danger" data-action="decline-call">Refuser</button><button class="btn primary" data-action="accept-call">Répondre</button></div></section>`)}
async function validateTask(id,approve){if(!['admin','manager'].includes(state.role))throw Error('Validation réservée aux responsables');let comment=approve?'Validé par '+person(state.user.id):prompt('Indique les corrections demandées :');if(comment===null)return;if(!approve&&!String(comment).trim())throw Error('Indique un commentaire pour les corrections');const client=await db();const {error}=await client.rpc('review_studio_task',{p_task:id,p_approve:approve,p_comment:String(comment).slice(0,2000)});if(error)throw error;close();await refresh();renderPage();toast(approve?'Production validée':'Corrections demandées')}
window.addEventListener('studio-call-status',e=>{const label=$('#studio-call-status');if(label)label.textContent=e.detail});
window.addEventListener('studio-call-error',e=>toast('Appel : '+e.detail));

async function act(name,el){try{if(name==='show-register'){registerScreen(document.querySelector('#login input[name=email]')?.value||'');return}if(name==='show-login'){auth();return}if(name==='start-call'){const c=items('conversations').find(x=>x.id===state.activeChat);if(!c||c.kind!=='Direct')throw Error('Les appels sont disponibles dans les conversations privées');const other=items('conversation_members').find(m=>m.conversation_id===c.id&&m.user_id!==state.user.id);if(!other)throw Error('Contact introuvable');openCallPanel(el.dataset.kind,'Appel vers '+conversationTitle(c));await placeCall({conversationId:c.id,calleeId:other.user_id,kind:el.dataset.kind});return}if(name==='accept-call'){const call=pendingCall;pendingCall=null;if(!call)return;openCallPanel(call.media_kind,'Appel avec '+person(call.caller_id));await acceptCall(call);return}if(name==='decline-call'){const call=pendingCall;pendingCall=null;close();if(call)await declineCall(call.id);return}if(name==='hangup-call'){await hangup();close();return}if(name==='read-notification'){const client=await db();const {error}=await client.from('notifications').update({read_at:new Date().toISOString()}).eq('id',el.dataset.id).eq('user_id',state.user.id);if(error)throw error;await refresh();renderPage();return}if(name==='approve-task'||name==='request-corrections'){return validateTask(el.dataset.id,name==='approve-task')} if(name==='show-saved')return showSavedMessages();if(name==='open-saved-message'){const mid=el.dataset.id;const msg=msgById(mid);if(!msg)return toast('Message introuvable');close();state.page='chat';state.activeChat=msg.conversation_id;state.chatView='thread';markChatRead(state.activeChat);return renderPage();}if(name==='message-menu')return messageMenu(el.dataset.id);if(name==='set-reaction')return setReaction(el.dataset.id,el.dataset.emoji||'❤️');if(name==='remove-reaction')return setReaction(el.dataset.id,'❤️',true);if(name==='chat-options')return conversationMenu(state.activeChat);if(name==='hide-chat'){const cid=el.dataset.id;const conversation=items('conversations').find(c=>c.id===cid);if(!conversation)return; if(!confirm('Retirer cette conversation uniquement de ta liste ? Elle restera disponible pour les autres participants et réapparaîtra si quelqu’un t’écrit.'))return;const client=await db();const {error}=await client.from('hidden_conversations').upsert({conversation_id:cid,workspace_id:state.workspace.id,user_id:state.user.id,hidden_at:new Date().toISOString()},{onConflict:'conversation_id,user_id'});if(error)throw error;if(state.activeChat===cid){state.activeChat=null;state.chatView='list';state.replyTo=null}close();await refresh();renderPage();toast('Conversation retirée de ta liste');return}if(name==='copy-message'){let m=msgById(el.dataset.id);await navigator.clipboard.writeText(m?.body||'');close();return toast('Message copié')}if(name==='share-message'){let m=msgById(el.dataset.id);if(navigator.share){try{await navigator.share({text:m?.body||''})}catch{}}else {await navigator.clipboard.writeText(m?.body||'');toast('Message copié pour le partage')}close();return}if(name==='reply-message')return startReply(el.dataset.id);if(name==='save-message')return toggleSave(el.dataset.id);if(name==='cancel-reply'){state.replyTo=null;return renderPage()}if(name==='back-chat'){close();state.chatView='list';state.activeChat=null;state.replyTo=null;return renderPage()}if(name==='open-schedule')return openScheduleFor(el.dataset.person);if(name==='open-my-schedule')return openScheduleFor(state.user.id);if(name==='new-slot'){close();return scheduleSlotForm(el.dataset.person||state.user.id)}if(name==='import-schedule'){state.schedulePerson=el.dataset.person||state.user.id;close();return importDialog('schedule')}if(name==='delete-slot'){if(!confirm('Supprimer ce créneau ?'))return;await remove('profile_schedules',el.dataset.id);close();await refresh();return openScheduleFor(state.schedulePerson||state.user.id)}if(name==='import-calendar')return importDialog('calendar');if(name==='import-task')return importDialog('task');if(name==='new-calendar')return newCalendarForm();if(name==='edit-calendar')return editCalendarForm(el.dataset.id);if(name==='delete-calendar'){const cal=items('studio_calendars').find(c=>c.id===el.dataset.id);if(!cal||cal.is_default)return toast('Impossible de supprimer le planning principal');if(!confirm(`Êtes-vous sûr de vouloir supprimer le planning « ${cal.name} » et tous ses événements ?`))return;if(!confirm(`DEUXIÈME CONFIRMATION : supprimer définitivement « ${cal.name} » et ses événements ?`))return;const {error}=await(await db()).rpc('delete_studio_calendar',{p_id:cal.id});if(error)throw error;state.calendarId=workspaceCalendar()?.id;await refresh();return renderPage()}if(name==='retry-data'){await refresh();return renderPage()}if(name==='retry')return initialize();if(name==='quick')return quickMenu();if(name==='open-profile')return profileEditor(el.dataset.id);if(name==='open-my-profile')return profileEditor();if(name==='open-document'){state.page='files';renderPage();return openDetail('document',el.dataset.id)}if(name==='delete-item'){const kind=el.dataset.kind,id=el.dataset.id;const tables={task:'tasks',event:'events',project:'projects',availability:'availability',conversation:'conversations',link:'external_links',message:'messages'};const table=tables[kind];if(!table)return;if(!confirm(kind==='conversation'?'Supprimer cette conversation et ses messages pour tous les participants ? Cette action est définitive.':'Supprimer définitivement cet élément ? Cette action ne peut pas être annulée.'))return;await remove(table,id);if(kind==='conversation'&&state.activeChat===id){state.activeChat=null;state.chatView='list';state.replyTo=null}close();await refresh();renderPage();return}if(name==='logout'){stopCalls();state.rows={};state.profile=[];state.activeChat=null;state.workspace=null;await(await db()).auth.signOut();return}if(name==='close'){if(document.querySelector('.call-panel'))await hangup();return close()}if(name==='new-task'){close();return taskForm()}if(name==='new-event'){close();return eventForm()}if(name==='new-conversation'){close();return conversationForm()}if(name==='new-availability'){close();return availabilityForm()}if(name==='new-file'){close();return uploadForm()}if(name==='new-link')return linkForm();if(name==='prev-month'||name==='next-month'){state.month=new Date(state.month.getFullYear(),state.month.getMonth()+(name==='prev-month'?-1:1),1);return renderPage()}if(name==='today'){state.month=new Date();return renderPage()}if(name==='select-chat'){close();state.activeChat=el.dataset.chat;state.chatView='thread';state.replyTo=null;markChatRead(state.activeChat);return renderPage()}if(name==='reset'){let email=state.user?.email||$('input[name=email]')?.value;if(!email)return toast('Saisissez votre adresse e-mail');let {error}=await(await db()).auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname});if(error)throw error;return toast('Si le compte existe, un e-mail de réinitialisation a été envoyé.')}if(name==='update'){if(!('serviceWorker'in navigator))return toast('Mises à jour non prises en charge');const reg=await navigator.serviceWorker.getRegistration();if(!reg)return toast('Service worker non installé');await reg.update();if(reg.waiting){if(confirm('Nouvelle version prête. Recharger ?'))reg.waiting.postMessage({type:'SKIP_WAITING'})}else toast('Vérification terminée. Aucune version prête détectée.');return}if(name==='download'){let d=items('documents').find(x=>x.id===el.dataset.id);const {data,error}=await(await db()).storage.from('studio-private').createSignedUrl(d.storage_path,60);if(error)throw error;window.open(data.signedUrl,'_blank','noopener');return}if(name==='toggle-keep'){const d=items('documents').find(x=>x.id===el.dataset.id);await mutate('documents',{keep:!d.keep},d.id);close();await refresh();return renderPage()}if(name==='delete-file'){if(!confirm('Supprimer définitivement ce fichier ?'))return;let d=items('documents').find(x=>x.id===el.dataset.id);let s=await db();let r=await s.storage.from('studio-private').remove([d.storage_path]);if(r.error)throw r.error;await remove('documents',d.id);close();await refresh();return renderPage()}}catch(e){toast('Erreur : '+e.message)}}
async function createConversation(kind,recipients,name){const client=await db();const ids=[...new Set(recipients.filter(x=>x!==state.user.id))];if(!ids.length)throw Error('Sélectionnez un destinataire');if(kind==='Direct'&&ids.length!==1)throw Error('Une conversation privée nécessite une personne');const {data,error}=await client.rpc('create_studio_conversation',{p_workspace:state.workspace.id,p_kind:kind,p_name:kind==='Direct'?'Privé':name||'Groupe',p_participants:ids});if(error)throw error;return data}
async function getDirectChat(other){const client=await db();const {data,error}=await client.rpc('get_or_create_direct_conversation',{p_workspace:state.workspace.id,p_other:other});if(error)throw error;return {id:data}}
async function submit(e){const form=e.target;
if(form.id==='register'){
 e.preventDefault();
 const fd=new FormData(form),email=String(fd.get('email')||'').trim().toLowerCase(),pw=String(fd.get('password')||''),confirmPw=String(fd.get('confirm')||'');
 const error=document.querySelector('#auth-error'),button=form.querySelector('button[type=submit]');
 if(!email || !email.includes('@')){error.textContent='Saisis ton adresse e-mail.';return}
 if(pw.length<8){error.textContent='Le mot de passe doit contenir au moins 8 caractères.';return}
 if(pw!==confirmPw){error.textContent='Les mots de passe ne correspondent pas.';return}
 button.disabled=true;
 try{
  const client=await db();
  const {data:{session}}=await client.auth.getSession();
  if(session?.user?.email?.toLowerCase()===email){
   const {error:changeErr}=await client.auth.updateUser({password:pw});
   if(changeErr)throw changeErr;
   await client.auth.signOut();state.user=null;auth();const msg=document.querySelector('#auth-error');if(msg){msg.style.color='var(--success,#87b4a3)';msg.textContent='Mot de passe enregistré. Connecte-toi avec ton nouvel accès.'}return;
  }
  if(session?.user?.email && session.user.email.toLowerCase()!==email){
   throw Error('Un autre compte est connecté dans ce navigateur. Ouvre une fenêtre de navigation privée pour activer cette adresse.');
  }
  const redirectTo=location.origin+location.pathname;
  const {data, error:signupErr}=await client.auth.signUp({email,password:pw,options:{emailRedirectTo:redirectTo}});
  if(signupErr){if(/already registered|already exists|user already/i.test(signupErr.message||'')){const reset=await client.auth.resetPasswordForEmail(email,{redirectTo});if(reset.error)throw reset.error;error.style.color='var(--success,#87b4a3)';error.textContent='Cette adresse est déjà enregistrée. Consulte le nouvel e-mail reçu pour choisir ton mot de passe.';return}throw signupErr;}
  if(data.user && Array.isArray(data.user.identities) && data.user.identities.length===0){
    const reset=await client.auth.resetPasswordForEmail(email,{redirectTo});
    if(reset.error)throw reset.error;
    error.style.color='var(--success,#87b4a3)';
    error.textContent='Cette adresse a déjà un compte. Ouvre le nouvel e-mail de réinitialisation pour définir ton mot de passe.';return;
  }
  if(data.session){await client.auth.signOut();state.user=null;auth();const msg=document.querySelector('#auth-error');if(msg){msg.style.color='var(--success,#87b4a3)';msg.textContent='Compte créé. Tu peux te connecter avec le mot de passe choisi.'}return}
  error.style.color='var(--success,#87b4a3)';
  error.textContent='Consulte ta boîte e-mail et confirme la création du compte avant de te connecter.';
 }catch(err){error.style.color='var(--danger,#e28d89)';error.textContent=err.message||'Création impossible.'}
 finally{button.disabled=false}
 return;
}

if(form.id==='set-password'){
 e.preventDefault();const fd=new FormData(form),pw=String(fd.get('password')||''),confirmPw=String(fd.get('confirm')||'');
 const error=document.querySelector('#auth-error');if(pw.length<8){error.textContent='Choisissez au moins 8 caractères.';return}
 if(pw!==confirmPw){error.textContent='Les deux mots de passe ne correspondent pas.';return}
 const button=form.querySelector('button[type=submit]');button.disabled=true;
 try{const client=await db();const {error:err}=await client.auth.updateUser({password:pw});if(err)throw err;await client.auth.signOut();state.user=null;auth();const msg=document.querySelector('#auth-error');if(msg){msg.style.color='var(--success,#68b78a)';msg.textContent='Mot de passe enregistré. Connectez-vous avec votre e-mail et ce nouveau mot de passe.'}}
 catch(err){error.textContent='Impossible de définir le mot de passe : '+err.message}finally{button.disabled=false}return
}
if(form.id==='login'){e.preventDefault();const f=new FormData(form);const s=await db();const {error}=await s.auth.signInWithPassword({email:f.get('email'),password:f.get('password')});if(error)$('#auth-error').textContent=error.message;return}if(form.id==='send-message'){e.preventDefault();const body=new FormData(form).get('message')?.trim();if(!body)return;const button=form.querySelector('button');button.disabled=true;try{await mutate('messages',{workspace_id:state.workspace.id,conversation_id:state.activeChat,author_id:state.user.id,body,reply_to:state.replyTo||null});state.replyTo=null;form.reset();await refresh();renderPage()}catch(err){toast('Message non envoyé : '+err.message)}finally{button.disabled=false}return}if(!form.dataset.form)return;e.preventDefault();const button=form.querySelector('button[type=submit],button:not([type])');if(button)button.disabled=true;let f=new FormData(form),kind=form.dataset.form,id=form.dataset.id;try{let record={workspace_id:state.workspace.id};if(kind==='edit-calendar'){const name=String(f.get('name')||'').trim();if(name.length<2)throw Error('Nom de planning trop court');await mutate('studio_calendars',{name,description:String(f.get('description')||'').trim()||null},id);}else if(kind==='calendar'){let c=await mutate('studio_calendars',{...record,name:String(f.get('name')).trim(),description:f.get('description')||null,created_by:state.user.id,is_default:false});state.calendarId=c.id;}else if(kind==='slot'){const fields={...record,user_id:form.dataset.person||state.user.id,created_by:state.user.id,weekday:Number(f.get('weekday')),specific_date:null,start_time:f.get('start_time'),end_time:f.get('end_time'),label:f.get('label')};if(fields.end_time<=fields.start_time)throw Error('La fin doit être après le début');await mutate('profile_schedules',fields)}else if(kind==='import'){await submitJsonImport(form,f);return;}else if(kind==='profile'){const values={display_name:String(f.get('display_name')||'').trim(),job_title:f.get('job_title')||null,color:f.get('color'),contact_url:f.get('contact_url')||null};if(values.contact_url&&!values.contact_url.startsWith('https://'))throw Error('Lien HTTPS requis');const photo=f.get('avatar');if(photo?.size){if(photo.size>2*1024*1024||!['image/jpeg','image/png','image/webp'].includes(photo.type))throw Error('Photo : JPG, PNG ou WebP, 2 Mo maximum');const ext=photo.type==='image/png'?'png':photo.type==='image/webp'?'webp':'jpg';const path=`${state.workspace.id}/avatars/${state.user.id}.${ext}`;const client=await db();const up=await client.storage.from('studio-avatars').upload(path,photo,{upsert:true,contentType:photo.type});if(up.error)throw up.error;values.avatar_url=path}const client=await db();const {data:updated,error}=await client.from('profiles').update(values).eq('id',state.user.id).select('id,display_name,color,avatar_url,job_title,contact_url').maybeSingle();if(error)throw error;if(!updated)throw Error('Le profil n’a pas été modifié. Vérifiez les droits RLS du compte.');}else if(kind==='file'){const file=f.get('file');if(!file?.size||file.size>50*1024*1024)throw Error('Fichier vide ou supérieur à 50 Mo');const path=`${state.workspace.id}/${crypto.randomUUID()}/${file.name.replace(/[^a-zA-Z0-9_.-]/g,'_')}`;const s=await db();$('#upload-progress').textContent='Transfert en cours…';await uploadStudioFile(s,path,file);try{const vis=f.get('visibility')||'workspace';const recipients=f.getAll('recipients');if(vis==='targeted'&&!recipients.length)throw Error('Choisissez au moins un destinataire');const doc=await mutate('documents',{...record,name:file.name,storage_path:path,mime_type:file.type||null,size_bytes:file.size,author_id:state.user.id,keep:f.has('keep'),visibility:vis});if(vis==='targeted'){const client=await db();const rows=recipients.map(user_id=>({document_id:doc.id,user_id}));const access=await client.from('document_recipients').insert(rows);if(access.error)throw access.error;for(const recipient of recipients){try{const conv=await getDirectChat(recipient);await mutate('messages',{workspace_id:state.workspace.id,conversation_id:conv.id,author_id:state.user.id,body:`Fichier partagé : ${file.name}`,document_id:doc.id})}catch(err){console.warn('Notification fichier',err)}}}}catch(e){await s.storage.from('studio-private').remove([path]);throw e}}else if(kind==='link'){let url=f.get('url');if(!url.startsWith('https://'))throw Error('Lien HTTPS requis');await mutate('external_links',{...record,title:f.get('title'),url,author_id:state.user.id},id)}else if(kind==='conversation'){const created=await createConversation(f.getAll('recipients').length===1?'Direct':'Groupe',f.getAll('recipients'),f.get('name'));const cid=typeof created==='string'?created:created?.id;if(cid){const cl=await db();await cl.from('hidden_conversations').delete().eq('conversation_id',cid).eq('user_id',state.user.id)}state.activeChat=null;state.chatView='list'}else if(kind==='task'){await mutate('tasks',{...record,title:f.get('title'),description:f.get('description'),priority:f.get('priority'),status:f.get('status'),assignee_id:f.get('assignee_id')||null,project_id:f.get('project_id')||null,due_at:f.get('due_at')||null,...(id?{}:{created_by:state.user.id})},id)}else if(kind==='event'){let start=new Date(f.get('starts_at')+'+04:00'),end=new Date(f.get('ends_at')+'+04:00');if(!(end>start))throw Error('La fin doit être après le début');await mutate('events',{...record,title:f.get('title'),category:f.get('category'),description:f.get('description'),location:f.get('location'),responsible_id:f.get('responsible_id')||null,calendar_id:f.get('calendar_id')||selectedCalendar()?.id||null,starts_at:start.toISOString(),ends_at:end.toISOString(),...(id?{}:{created_by:state.user.id})},id)}else if(kind==='project'){await mutate('projects',{...record,name:f.get('name'),category:f.get('category'),status:f.get('status'),description:f.get('description'),...(id?{}:{created_by:state.user.id})},id)}else if(kind==='availability'){let start=new Date(f.get('starts_at')+'+04:00'),end=new Date(f.get('ends_at')+'+04:00');if(!(end>start))throw Error('Dates incorrectes');await mutate('availability',{...record,user_id:f.get('user_id')||state.user.id,label:f.get('label'),kind:f.get('kind'),starts_at:start.toISOString(),ends_at:end.toISOString()},id)}close();toast('Enregistré sur le serveur');await refresh();renderPage()}catch(err){toast('Enregistrement impossible : '+err.message)}finally{if(button)button.disabled=false}}
async function uploadStudioFile(client,path,file){
 const progress=document.querySelector('#upload-progress');
 if(file.size<=6*1024*1024){
   const result=await client.storage.from('studio-private').upload(path,file,{upsert:false,contentType:file.type||'application/octet-stream'});
   if(result.error)throw result.error;
   return;
 }
 const {data:{session}}=await client.auth.getSession();
 if(!session?.access_token)throw Error('Reconnecte-toi pour transmettre ce fichier');
 let tus;
 try{tus=await import('https://cdn.jsdelivr.net/npm/tus-js-client@4/+esm')}catch{throw Error('Téléversement volumineux indisponible : vérifie ta connexion internet')}
 const projectId=new URL(SUPABASE_URL).hostname.split('.')[0];
 await new Promise((resolve,reject)=>{
  const upload=new tus.Upload(file,{
   endpoint:`https://${projectId}.storage.supabase.co/storage/v1/upload/resumable`,
   retryDelays:[0,3000,5000,10000],
   headers:{authorization:`Bearer ${session.access_token}`,apikey:SUPABASE_PUBLISHABLE_KEY,'x-upsert':'false'},
   uploadDataDuringCreation:true,removeFingerprintOnSuccess:true,
   metadata:{bucketName:'studio-private',objectName:path,contentType:file.type||'application/octet-stream',cacheControl:'3600'},
   chunkSize:6*1024*1024,
   onError:reject,onSuccess:resolve,
   onProgress:(sent,total)=>{if(progress)progress.textContent=`Transfert : ${Math.round(sent*100/total)} %`}
  });upload.start();
 });
}

// === MAHAVEL 0.3 — fonctions complémentaires ===
const dayNames=['Lundi','Mardi','Mercredi','Jeudi','Vendredi','Samedi','Dimanche'];
const msgById=id=>items('messages').find(m=>m.id===id);
const profileById=id=>state.profile.find(p=>p.id===id);
const userColor=()=>safeColor(profileById(state.user.id)?.color);
function setPersonTheme(){document.documentElement.style.setProperty('--person-accent',userColor())}
function messageMarkup(m){
 const mine=m.author_id===state.user.id, reactions=items('message_reactions').filter(r=>r.message_id===m.id),saved=items('saved_messages').some(s=>s.message_id===m.id&&s.user_id===state.user.id);
 const reply=msgById(m.reply_to); const replyPart=reply?`<div class="quoted-mini">↳ ${html(person(reply.author_id))} : ${html(reply.body.slice(0,110))}</div>`:'';
 return `<article class="chat-message ${mine?'mine':'theirs'}" data-message-id="${m.id}" data-author="${m.author_id}" style="--sender:${colorOf(m.author_id)}" tabindex="0" aria-label="Message de ${html(person(m.author_id))}. Appui long pour les actions"><div class="bubble"><div class="msg-author">${html(person(m.author_id))}</div>${replyPart}<div class="msg-body">${html(m.body)}</div>${m.document_id?`<button class="btn small" data-action="open-document" data-id="${m.document_id}">${icon('files')} Voir le fichier</button>`:''}<div class="msg-meta">${hour(m.created_at)} ${saved?' · Enregistré':''}</div></div>${reactions.length?`<div class="message-reactions">${[...new Set(reactions.map(r=>r.emoji||'❤️'))].map(emoji=>{const count=reactions.filter(r=>(r.emoji||'❤️')===emoji).length;const mine=reactions.some(r=>r.user_id===state.user.id&&(r.emoji||'❤️')===emoji);return `<button type="button" class="reaction-badge ${mine?'mine-reaction':''}" data-action="set-reaction" data-id="${m.id}" data-emoji="${html(emoji)}" title="${mine?'Retirer ma réaction':'Réagir avec '+emoji}">${html(emoji)} ${count}</button>`}).join('')}</div>`:''}<button class="msg-dots" data-action="message-menu" data-id="${m.id}" aria-label="Actions du message">···</button></article>`;
}
function showSavedMessages(){const saved=new Set(items('saved_messages').filter(x=>x.user_id===state.user.id).map(x=>x.message_id));const messages=items('messages').filter(x=>saved.has(x.id)).sort((a,b)=>b.created_at.localeCompare(a.created_at));modal('Mes messages enregistrés',`<p class="note">Ces messages restent accessibles après les 7 jours habituels tant qu'ils sont enregistrés.</p><div class="saved-list">${messages.length?messages.map(m=>`<button type="button" class="saved-row" data-action="open-saved-message" data-id="${m.id}"><strong>${html(person(m.author_id))}</strong><span>${html(m.body.slice(0,180))}</span><small>${html(fmt(m.created_at))}</small></button>`).join(''):'<div class="empty">Aucun message enregistré pour le moment.</div>'}</div>`)}
function messageMenu(mid){const m=msgById(mid);if(!m)return;const saved=items('saved_messages').some(s=>s.message_id===mid&&s.user_id===state.user.id);
 const mine=m.author_id===state.user.id;const myReaction=items('message_reactions').find(r=>r.message_id===mid&&r.user_id===state.user.id);
 modal('Actions du message',`<div class="message-quote"><span style="color:${colorOf(m.author_id)}">${html(person(m.author_id))}</span><p>${html(m.body.slice(0,350))}</p></div><div class="emoji-choices" role="group" aria-label="Réagir au message">${['❤️','😂','😮','😢','😡','👍','🔥','🥰','👏','🎉'].map(emoji=>`<button type="button" class="emoji-choice ${myReaction?.emoji===emoji?'selected':''}" data-action="set-reaction" data-id="${m.id}" data-emoji="${html(emoji)}" aria-label="Réagir avec ${emoji}">${emoji}</button>`).join('')}</div>${myReaction?`<button type="button" class="context-action remove-reaction" data-action="remove-reaction" data-id="${m.id}">Retirer ma réaction ${html(myReaction.emoji||'❤️')}</button>`:''}<div class="context-actions"><button class="context-action" data-action="copy-message" data-id="${m.id}">${icon('copy')} Copier</button><button class="context-action" data-action="reply-message" data-id="${m.id}">${icon('reply')} Répondre</button><button class="context-action" data-action="share-message" data-id="${m.id}">${icon('share')} Partager</button><button class="context-action" data-action="save-message" data-id="${m.id}">${icon('bookmark')} ${saved?'Retirer de mes messages enregistrés':'Enregistrer au-delà de 7 jours'}</button>${mine?`<button class="context-action dangerous" data-action="delete-item" data-kind="message" data-id="${m.id}">${icon('trash')} Supprimer</button>`:''}</div>`);
}
async function setReaction(mid,emoji='❤️',forceRemove=false){
 const accepted=['❤️','😂','😮','😢','😡','👍','🔥','🥰','👏','🎉'];
 if(!accepted.includes(emoji))throw Error('Réaction non disponible');
 const client=await db();
 const mine=items('message_reactions').find(r=>r.message_id===mid&&r.user_id===state.user.id);
 if(mine){
  const {error}=await client.from('message_reactions').delete().eq('message_id',mid).eq('user_id',state.user.id);
  if(error)throw error;
 }
 if(!forceRemove && (!mine || (mine.emoji||'❤️')!==emoji)){
  const {error}=await client.from('message_reactions').insert({message_id:mid,user_id:state.user.id,emoji});
  if(error)throw error;
 }
 close();await refresh();renderPage();
}
async function toggleLike(mid){return setReaction(mid,'❤️')}
async function toggleSave(mid){const client=await db();const saved=items('saved_messages').some(s=>s.message_id===mid&&s.user_id===state.user.id);const q=saved?client.from('saved_messages').delete().eq('message_id',mid).eq('user_id',state.user.id):client.from('saved_messages').insert({message_id:mid,user_id:state.user.id});const {error}=await q;if(error)throw error;close();await refresh();renderPage();toast(saved?'Message retiré des enregistrements':'Message conservé au-delà de 7 jours')}
function startReply(mid){const m=msgById(mid);if(!m)return;state.replyTo=mid;close();state.page='chat';renderPage();document.querySelector('#send-message input')?.focus({preventScroll:true})}
function workspaceCalendar(){return items('studio_calendars').find(c=>c.is_default)}
function selectedCalendar(){const all=items('studio_calendars');return all.find(c=>c.id===state.calendarId)||all.find(c=>c.is_default)||all[0]}
function editCalendarForm(id){const cal=items('studio_calendars').find(x=>x.id===id);if(!cal||cal.is_default)return toast('Le planning principal est protégé');if(cal.created_by!==state.user.id&&state.role==='member')return toast('Modification réservée au créateur ou responsable');modal('Modifier le planning',`<form data-form="edit-calendar" data-id="${cal.id}"><div><label>Nouveau nom</label><input name="name" required maxlength="100" minlength="2" value="${html(cal.name)}"></div><div><label>Description</label><input name="description" maxlength="200" value="${html(cal.description||'')}"></div><div class="actions"><button class="btn primary" type="submit">Enregistrer les modifications</button></div></form>`)}
function newCalendarForm(){modal('Créer un planning',`<form data-form="calendar"><div><label>Nom du planning</label><input name="name" required maxlength="100" placeholder="Ex. CinéKlap ou Éditorial MAHAVEL"></div><div><label>Description (facultatif)</label><input name="description" maxlength="200" placeholder="À quoi sert ce calendrier ?"></div><div class="actions"><button class="btn primary">Créer le planning</button></div></form>`)}
function importDialog(kind){const titles={calendar:'Importer un planning',task:'Importer des tâches',schedule:'Importer un emploi du temps'};const sample={calendar:'mahavel-calendar-v1',task:'mahavel-tasks-v1',schedule:'mahavel-schedule-v1'};modal(titles[kind],`<form data-form="import" data-import="${kind}" ${kind==='schedule'?`data-person="${html(state.schedulePerson||state.user.id)}"`:''}><p class="note">Choisis un fichier JSON au format <strong>${sample[kind]}</strong>. L'application vérifie les informations avant de les enregistrer. Tu peux me fournir ton planning ou tes tâches dans le chat pour que je prépare ce fichier.</p><label>Fichier JSON</label><input type="file" name="import_file" accept=".json,application/json" required><div class="actions"><button class="btn primary">Vérifier et importer</button></div></form>`)}
function schedulePageFor(id){const personName=person(id);const rows=items('profile_schedules').filter(x=>x.user_id===id).sort((a,b)=>String(a.specific_date||a.weekday).localeCompare(String(b.specific_date||b.weekday))||a.start_time.localeCompare(b.start_time));const canEdit=id===state.user.id||state.role!=='member';return `<div class="profile-schedule"><div class="schedule-heading"><h3>Emploi du temps · ${html(personName)}</h3>${canEdit?`<div class="controls"><button class="btn" data-action="new-slot" data-person="${id}">+ Créneau</button><button class="btn" data-action="import-schedule" data-person="${id}">Importer JSON</button></div>`:''}</div>${rows.length?rows.map(s=>`<div class="schedule-slot"><span>${s.specific_date?html(s.specific_date):dayNames[s.weekday]}</span><b>${html(s.start_time.slice(0,5))}–${html(s.end_time.slice(0,5))}</b><span>${html(s.label)}</span>${canEdit?`<button class="btn small danger" data-action="delete-slot" data-id="${s.id}">Supprimer</button>`:''}</div>`).join(''):'<div class="empty">Pas d’emploi du temps pour le moment</div>'}<p class="note">Les créneaux récurrents sont affichés en heure de La Réunion. Pour un PDF, envoie-le dans ce chat : je pourrai préparer un fichier JSON compatible après lecture du document.</p></div>`}
function openScheduleFor(id){state.schedulePerson=id;modal('Emploi du temps',schedulePageFor(id))}
function scheduleSlotForm(id){state.schedulePerson=id;modal('Ajouter un créneau',`<form data-form="slot" data-person="${id}"><label>Jour de la semaine</label><select name="weekday">${dayNames.map((v,i)=>`<option value="${i}">${v}</option>`).join('')}</select><label>Début</label><input name="start_time" type="time" required value="08:00"><label>Fin</label><input name="end_time" type="time" required value="17:00"><label>Intitulé</label><input name="label" maxlength="120" value="Travail" required><div class="actions"><button class="btn primary">Ajouter</button></div></form>`)}
function sanitizeSchedule(rows,personId){if(!Array.isArray(rows)||!rows.length||rows.length>150)throw Error('Le fichier doit contenir de 1 à 150 créneaux');return rows.map((x,i)=>{let row={workspace_id:state.workspace.id,user_id:personId,created_by:state.user.id,weekday:x.weekday===null?null:Number(x.weekday),specific_date:x.date||null,start_time:x.start,end_time:x.end,label:String(x.label||'Travail').slice(0,120)};if(row.specific_date){row.weekday=null;if(!/^\d{4}-\d{2}-\d{2}$/.test(row.specific_date))throw Error(`Ligne ${i+1} : date incorrecte`)}else if(!Number.isInteger(row.weekday)||row.weekday<0||row.weekday>6)throw Error(`Ligne ${i+1} : jour incorrect`);if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(row.start_time||'')||!/^([01]\d|2[0-3]):[0-5]\d$/.test(row.end_time||'')||row.end_time<=row.start_time)throw Error(`Ligne ${i+1} : horaire incorrect`);return row})}
async function hashImportKey(kind,record){const stable=kind==='schedule'?['schedule',record.user_id,record.weekday,record.specific_date,record.start_time,record.end_time,String(record.label).trim().toLocaleLowerCase('fr')]:kind==='task'?['task',String(record.title).trim().toLocaleLowerCase('fr'),record.due_at,record.assignee_id]:['event',record.calendar_id,String(record.title).trim().toLocaleLowerCase('fr'),record.starts_at,record.ends_at];const bytes=new TextEncoder().encode(JSON.stringify(stable));const raw=await crypto.subtle.digest('SHA-256',bytes);return Array.from(new Uint8Array(raw),b=>b.toString(16).padStart(2,'0')).join('')}
async function insertNewImported(table,kind,rows,original){const existing=items(table);const seen=new Set();const fresh=[];for(const row of rows){row.import_key=await hashImportKey(kind,row);let exists=seen.has(row.import_key)||existing.some(x=>x.import_key===row.import_key);if(!exists){if(kind==='task')exists=existing.some(x=>String(x.title).trim().toLocaleLowerCase('fr')===String(row.title).trim().toLocaleLowerCase('fr')&&(x.due_at||null)===(row.due_at||null)&&x.assignee_id===row.assignee_id);else if(kind==='event')exists=existing.some(x=>x.calendar_id===row.calendar_id&&String(x.title).trim().toLocaleLowerCase('fr')===String(row.title).trim().toLocaleLowerCase('fr')&&x.starts_at===row.starts_at&&x.ends_at===row.ends_at);else exists=existing.some(x=>x.user_id===row.user_id&&x.weekday===row.weekday&&(x.specific_date||null)===(row.specific_date||null)&&x.start_time===row.start_time&&x.end_time===row.end_time&&String(x.label).trim().toLocaleLowerCase('fr')===String(row.label).trim().toLocaleLowerCase('fr'))}seen.add(row.import_key);if(!exists)fresh.push(row)}const duplicates=rows.length-fresh.length;if(!fresh.length){toast(`${duplicates} doublon(s) détecté(s) : aucune donnée ajoutée`);return 0}if(!confirm(`${fresh.length} élément(s) à importer, ${duplicates} doublon(s) ignoré(s). Continuer ?`))return -1;const client=await db();const {error}=await client.from(table).upsert(fresh,{onConflict:'workspace_id,import_key',ignoreDuplicates:true});if(error)throw error;toast(`${fresh.length} ajouté(s), ${duplicates} doublon(s) ignoré(s)`);return fresh.length}
async function submitJsonImport(form,f){let file=f.get('import_file');if(!file?.size||file.size>500000)throw Error('Fichier JSON absent ou trop gros (500 Ko max)');let obj;try{obj=JSON.parse(await file.text())}catch{throw Error('Le fichier n’est pas un JSON valide')};const kind=form.dataset.import,client=await db();if(kind==='schedule'){if(obj.format!=='mahavel-schedule-v1')throw Error('Format d’emploi du temps incorrect');let target=form.dataset.person||state.user.id;if(target!==state.user.id&&state.role==='member')throw Error('Permissions insuffisantes');let rows=sanitizeSchedule(obj.slots,target);const n=await insertNewImported('profile_schedules','schedule',rows);if(n<0)return}
else if(kind==='task'){if(obj.format!=='mahavel-tasks-v1'||!Array.isArray(obj.tasks)||obj.tasks.length<1||obj.tasks.length>100)throw Error('Format des tâches incorrect ou trop d’entrées');const statuses=['À faire','En cours','En attente','À valider','Corrections demandées','Terminé','Archivé'];const rows=obj.tasks.map((x,i)=>{const responsible=x.assignee_email?state.profile.find(p=>p.contact_email?.toLowerCase()===String(x.assignee_email).toLowerCase()):null;if(x.assignee_email&&!responsible)throw Error(`Tâche ${i+1} : destinataire introuvable`);if(!String(x.title||'').trim())throw Error(`Tâche ${i+1} : titre manquant`);if(x.due_date&&!/^\d{4}-\d{2}-\d{2}$/.test(x.due_date))throw Error(`Tâche ${i+1} : date incorrecte`);return {workspace_id:state.workspace.id,created_by:state.user.id,title:String(x.title).trim().slice(0,200),description:String(x.description||''),assignee_id:responsible?.id||state.user.id,priority:['Normale','Haute','Urgente'].includes(x.priority)?x.priority:'Normale',status:statuses.includes(x.status)?x.status:'À faire',due_at:x.due_date||null}});const n=await insertNewImported('tasks','task',rows);if(n<0)return}
else if(kind==='calendar'){if(obj.format!=='mahavel-calendar-v1'||!obj.calendar?.name||!Array.isArray(obj.events)||!obj.events.length||obj.events.length>150)throw Error('Format du planning incorrect (1 à 150 événements attendus)');const names=items('studio_calendars');let cal=names.find(c=>c.name.toLowerCase()===String(obj.calendar.name).trim().toLowerCase());const rows=obj.events.map((x,i)=>{const start=new Date(x.start),end=new Date(x.end);if(!x.title||!Number.isFinite(start.getTime())||!Number.isFinite(end.getTime())||end<=start)throw Error(`Événement ${i+1} : titre ou dates incorrects`);return {workspace_id:state.workspace.id,created_by:state.user.id,title:String(x.title).trim().slice(0,200),description:String(x.description||''),category:String(x.category||'Autre'),location:String(x.location||''),starts_at:start.toISOString(),ends_at:end.toISOString(),responsible_id:state.user.id}});let created=false;if(!cal){const {data,error}=await client.from('studio_calendars').insert({workspace_id:state.workspace.id,name:String(obj.calendar.name).slice(0,100),description:String(obj.calendar.description||'').slice(0,200),created_by:state.user.id}).select('id,name').single();if(error)throw error;cal=data;created=true}rows.forEach(r=>r.calendar_id=cal.id);try{const n=await insertNewImported('events','event',rows);if(n<0)return;state.calendarId=cal.id}catch(error){if(created)await client.from('studio_calendars').delete().eq('id',cal.id);throw error}}
else throw Error('Type d’import inconnu');close();await refresh();renderPage()}
// Appui long : messages et conversations. Menu contextuel également accessible par le clavier.
let gestureTimer=null,gestureStart=null,lastTap={id:null,time:0},suppressTapUntil=0;
document.addEventListener('pointerdown',e=>{const item=e.target.closest('[data-message-id],[data-chat-id]');if(!item||e.target.closest('button,input,textarea'))return;gestureStart={x:e.clientX,y:e.clientY,id:item.dataset.messageId||item.dataset.chatId,type:item.dataset.messageId?'message':'chat',time:Date.now()};clearTimeout(gestureTimer);gestureTimer=setTimeout(()=>{if(gestureStart){suppressTapUntil=Date.now()+650;if(gestureStart.type==='message')messageMenu(gestureStart.id);else conversationMenu(gestureStart.id);gestureStart=null}},560)});
document.addEventListener('pointermove',e=>{if(gestureStart&&(Math.abs(e.clientX-gestureStart.x)>15||Math.abs(e.clientY-gestureStart.y)>15)){clearTimeout(gestureTimer)}});
document.addEventListener('pointerup',e=>{clearTimeout(gestureTimer);if(!gestureStart)return;let g=gestureStart;gestureStart=null;const dx=e.clientX-g.x,dy=e.clientY-g.y;if(g.type==='message'&&Math.abs(dx)>65&&Math.abs(dy)<55){suppressTapUntil=Date.now()+350;startReply(g.id);return}if(g.type==='message'&&Math.abs(dx)<14&&Math.abs(dy)<14){if(lastTap.id===g.id&&Date.now()-lastTap.time<340){lastTap.id=null;toggleLike(g.id).catch(err=>toast(err.message))}else lastTap={id:g.id,time:Date.now()}}});
document.addEventListener('pointercancel',()=>{clearTimeout(gestureTimer);gestureStart=null});
document.addEventListener('contextmenu',e=>{const msg=e.target.closest('[data-message-id]');const chat=e.target.closest('[data-chat-id]');if(msg){e.preventDefault();messageMenu(msg.dataset.messageId)}else if(chat){e.preventDefault();conversationMenu(chat.dataset.chatId)}});
function conversationMenu(cid){const c=items('conversations').find(x=>x.id===cid);if(!c)return;modal('Conversation',`<div class="message-quote">${html(conversationTitle(c))}</div><div class="context-actions"><button type="button" class="context-action" data-action="back-chat">← Fermer et revenir aux discussions</button><button type="button" class="context-action" data-action="select-chat" data-chat="${cid}">${icon('chat')} Ouvrir</button><button type="button" class="context-action dangerous" data-action="hide-chat" data-id="${cid}">${icon('trash')} Supprimer de ma liste uniquement</button>${c.created_by===state.user.id?`<button type="button" class="context-action dangerous" data-action="delete-item" data-kind="conversation" data-id="${cid}">${icon('trash')} Supprimer définitivement pour tous</button>`:''}</div>`)}

document.addEventListener('click',e=>{if(Date.now()<suppressTapUntil&&!e.target.closest('.modalbg')){e.preventDefault();return}const n=e.target.closest('[data-nav]');if(n){state.page=n.dataset.nav;renderPage();return}const a=e.target.closest('[data-action]');if(a){act(a.dataset.action,a);return}const o=e.target.closest('[data-open]');if(o){const [kind,id]=o.dataset.open.split(':');openDetail(kind,id)}});document.addEventListener('submit',submit);document.addEventListener('input',e=>{if(e.target?.id==='chat-search'){state.chatSearch=e.target.value;document.querySelectorAll('.chat-contact').forEach(el=>{el.hidden=!el.innerText.toLocaleLowerCase('fr').includes(state.chatSearch.toLocaleLowerCase('fr'))})}});document.addEventListener('change',e=>{if(e.target.id==='task-filter')$('#task-table').innerHTML=taskRows(e.target.value);if(e.target.id==='calendar-selector'){state.calendarId=e.target.value;renderPage()}const form=e.target.closest('form');if(form?.dataset.form==='conversation'){const count=form.querySelectorAll('[name=recipients]:checked').length;const label=form.querySelector('#chat-count');if(label)label.textContent=`${count} sélectionné(e)${count>1?'s':''}`;const group=form.querySelector('#group-name-wrap');if(group)group.hidden=count<2}if(form?.dataset.form==='file'){const target=form.querySelector('#file-recipients');if(target)target.hidden=form.querySelector('[name=visibility]').value!=='targeted';const count=form.querySelectorAll('[name=recipients]:checked').length;const label=form.querySelector('#file-count');if(label)label.textContent=`${count} sélectionné(e)${count>1?'s':''}`}});window.addEventListener('online',()=>{$('#connection')?.classList.remove('offline');if($('#connection'))$('#connection').innerHTML='<i></i><span>En ligne</span>';refresh().then(renderPage)});window.addEventListener('offline',()=>{if($('#connection')){$('#connection').classList.add('offline');$('#connection').innerHTML='<i></i><span>Hors ligne</span>'}});navigator.serviceWorker?.addEventListener('controllerchange',()=>{if(!document.querySelector('.modalbg, input:focus, textarea:focus, input[type=file]'))location.reload();else toast('Mise à jour prête : terminez votre saisie puis rechargez la page')});if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(console.warn));initialize();
